def naive_union(df, key, start_col='start', end_col='end', gap=pd.Timedelta(0)):
    if df.empty:
        return pd.DataFrame(columns=[key, start_col, end_col])

    res = []
    for k, g in df.groupby(key):
        # sort intervals
        intervals = sorted(zip(g[start_col], g[end_col]))
        merged = []
        cur_s, cur_e = intervals[0]
        for s, e in intervals[1:]:
            if s <= cur_e + gap:
                cur_e = max(cur_e, e)
            else:
