"import os
import re

def search(pattern):
    root = '.'
    matches = []
    for dirpath, dirnames, filenames in os.walk(root):
        if any(skip in dirpath for skip in ['.git', '__pycache__', '.pytest_cache', 'scratch', 'scratch-gpro']):
            continue
        for fname in filenames:
            if fname.endswith(('.py', '.md', '.yaml', '.json')):
                fpath = os.path.join(dirpath, fname)
                try:
                    with open(fpath, 'r', encoding='utf-8') as f:
                        for lnum, line in enumerate(f, 1):
                            if re.search(pattern, line):
                                matches.append((fpath, lnum, line.strip()))
                except Exception:
                    pass
    return matches

print("Search for seconds_since_start:")
for m in search(r'seconds_since_start'):
    print(f"{m[0]}:{m[1]}: {m[2]}")
